1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"unicode/utf8"
14	)
15	
16	// Check statuses recorded per rule in a report.
17	const (
18		StatusUnchecked   = "未检查"
19		StatusPass        = "通过"
20		StatusDefect      = "发现缺陷"
21		StatusToolMissing = "工具缺失"
22		StatusTimeout     = "超时"
23	)
24	
25	// ReportArtifact identifies the audited artifact by name and content hash.
26	type ReportArtifact struct {
27		Name string `json:"name"`
28		Hash string `json:"hash"`
29	}
30	
31	// ReportRule is one rule together with the invariant check result. The note
32	// carries the original checker description: counterexample evidence for a
33	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
34	// or an optional remark for a passing check. It is empty for reports built
35	// only from invariant booleans.
36	type ReportRule struct {
37		ID          string `json:"id"`
38		Kind        string `json:"kind"`
39		Severity    string `json:"severity"`
40		Invariant   string `json:"invariant"`
41		RequiresABI bool   `json:"requiresABI"`
42		Version     string `json:"version"`
43		Status      string `json:"status"`
44		Note        string `json:"note,omitempty"`
45	}
46	
47	// ReportFinding binds a defect to its artifact, rule, version and evidence.
48	type ReportFinding struct {
49		ArtifactHash string `json:"artifactHash"`
50		RuleID       string `json:"ruleId"`
51		Version      string `json:"version"`
52		Severity     string `json:"severity"`
53		Invariant    string `json:"invariant"`
54		Evidence     string `json:"evidence"`
55	}
56	
57	// Report is the persisted audit result.
58	type Report struct {
59		ReportID string          `json:"reportId"`
60		Artifact ReportArtifact  `json:"artifact"`
61		Rules    []ReportRule    `json:"rules"`
62		Findings []ReportFinding `json:"findings"`
63	}
64	
65	// wireArtifact is the JSON shape of an artifact in an audit submission.
66	type wireArtifact struct {
67		Name     string `json:"name"`
68		ABI      string `json:"abi"`
69		Bytecode string `json:"bytecode"`
70		Source   string `json:"source"`
71	}
72	
73	// wireRule is the JSON shape of a rule in an audit submission.
74	type wireRule struct {
75		ID          string `json:"id"`
76		Kind        string `json:"kind"`
77		Severity    string `json:"severity"`
78		Invariant   string `json:"invariant"`
79		RequiresABI bool   `json:"requiresABI"`
80		Version     string `json:"version"`
81	}
82	
83	// CheckRecord is one imported per-rule check result: the artifact hash and
84	// rule version it was produced against, the conclusion status, and the
85	// original checker note (counterexample, tool or deadline remark).
86	type CheckRecord struct {
87		ArtifactHash string
88		RuleID       string
89		Version      string
90		Status       string
91		Note         string
92	}
93	
94	// wireCheck is the JSON shape of one entry in the checks array.
95	type wireCheck struct {
96		ArtifactHash string `json:"artifactHash"`
97		RuleID       string `json:"ruleId"`
98		Version      string `json:"version"`
99		Status       string `json:"status"`
100		Note         string `json:"note"`
101	}
102	
103	// wireInput is the JSON object accepted by the audit command.
104	type wireInput struct {
105		Artifact   wireArtifact               `json:"artifact"`
106		Rules      []wireRule                 `json:"rules"`
107		Invariants map[string]json.RawMessage `json:"invariants"`
108		Checks     []wireCheck                `json:"checks"`
109	}
110	
111	// submissionShape is the fixed-field shape of an audit submission: the agreed
112	// spellings at the top level and inside the artifact, every rule and every
113	// check record. The invariants object is a fixed top-level member but has no
114	// nested shape, so it passes through untouched: invariant names are
115	// user-defined rather than fixed fields, and "Inv" and "inv" stay two
116	// independent invariants and a padded name is not trimmed.
117	var submissionShape = fixedShape{
118		keys: []string{"artifact", "rules", "invariants", "checks"},
119		objects: map[string]fixedShape{
120			"artifact": {keys: []string{"name", "abi", "bytecode", "source"}},
121		},
122		arrays: map[string]fixedShape{
123			"rules":  {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}},
124			"checks": {keys: []string{"artifactHash", "ruleId", "version", "status", "note"}},
125		},
126	}
127	
128	// strictSubmissionJSON rewrites submission bytes to the fixed submission
129	// fields under their agreed spelling; see fixedShape for the recognition
130	// convention shared with the archive read side.
131	func strictSubmissionJSON(data []byte) ([]byte, error) {
132		return strictFixedJSON(data, submissionShape)
133	}
134	
135	// validateFormalCheckStatuses checks the formal "status" member of every
136	// strict check record. The strict rewrite dropped extension members, so the
137	// status seen here is the agreed-spelling one alone: a missing formal status,
138	// a non-string one, or an unsupported value rejects the whole submission
139	// even when an adjacent "StAtus" extension member carried a legal-looking
140	// value. The error names the rule the record is for so the offending entry is
141	// identifiable.
142	func validateFormalCheckStatuses(strict []byte) error {
143		var top struct {
144			Checks []map[string]json.RawMessage `json:"checks"`
145		}
146		if err := json.Unmarshal(strict, &top); err != nil {
147			return errInvalid("invalid JSON: " + err.Error())
148		}
149		for _, rec := range top.Checks {
150			where := "check record"
151			if raw, ok := rec["ruleId"]; ok {
152				var ruleID string
153				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
154					where = "check for rule " + ruleID
155				}
156			}
157			raw, ok := rec["status"]
158			if !ok {
159				return errInvalid(where + ": status is required")
160			}
161			var status string
162			if err := json.Unmarshal(raw, &status); err != nil {
163				return errInvalid(where + ": status must be a string")
164			}
165			if !validCheckStatus(status) {
166				return errInvalid(where + ": unknown status " + status)
167			}
168		}
169		return nil
170	}
171	
172	// validateFormalRequiresABI checks the formal "requiresABI" member of every
173	// strict rule definition in an audit submission; the written-means-boolean
174	// rule and the per-rule walk are shared with the archive side in
175	// checkRuleFieldTypes. The strict rewrite dropped extension members, so the
176	// value seen here is the agreed-spelling one alone. Decoding the member
177	// straight into a Go bool would turn null into the zero value false: a rule
178	// whose requirement was never actually stated would be recorded as not
179	// needing an ABI, indistinguishable from an explicit false, and could even
180	// produce a defect finding from a false invariant. When the formal member is
181	// present its value must be the JSON boolean true or false — null, a string,
182	// a number, an object or an array rejects the whole submission, whether or
183	// not the artifact carries an ABI and whether or not the rule received any
184	// check conclusion. An omitted member still means false. A case-variant or
185	// whitespace-padded name is extension data and its value, null included,
186	// never reaches this check; it can neither trigger the error nor rescue an
187	// illegal formal value. The error names the rule so the offending entry is
188	// identifiable and is an input error.
189	func validateFormalRequiresABI(strict []byte) error {
190		return checkRuleFieldTypes(strict,
191			[]ruleFieldTypeCheck{{field: "requiresABI", typ: ruleFieldBoolean}},
192			ruleFieldTypeHooks{
193				locate: func(_ int, rule map[string]json.RawMessage) string {
194					if id := formalRuleID(rule); id != "" {
195						return "rule " + id
196					}
197					return "rule"
198				},
199				invalidJSON: func(err error) error { return errInvalid("invalid JSON: " + err.Error()) },
200				reject: func(where, field string, typ ruleFieldType) error {
201					return errInvalid(where + ": " + field + " " + typ.requirement())
202				},
203			})
204	}
205	
206	// ParseAuditInput decodes an audit submission JSON object into domain values.
207	// Invariant values must be JSON booleans; any other type is an error. A formal
208	// requiresABI member on a rule must likewise be a JSON boolean: null or any
209	// non-boolean value rejects the whole submission instead of being read as the
210	// zero value false, while an omitted member still means false. Any JSON
211	// object in the submission that repeats a member name rejects the whole
212	// submission: the decoder keeps only the last value silently, so a repeated
213	// invariant key would choose a conclusion by member order instead of giving
214	// one trustworthy result. A character the decoder would silently rewrite — an
215	// invalid UTF-8 byte, or an unpaired or wrongly ordered surrogate escape in
216	// any member name or string value, including values nested under unknown
217	// extension members — rejects the whole submission as an input error before
218	// any content is hashed, so evidence and hashes always reflect the submitted
219	// bytes rather than a U+FFFD-rewritten copy. Only the fixed fields under their
220	// agreed spelling participate: case variants and whitespace-padded names are
221	// extension data and are ignored, so they can neither override a formal value
222	// nor supply one when the formal member is missing or unsupported. Invariant
223	// names are not fixed fields — they are user-defined, compared case
224	// sensitively and never trimmed.
225	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
226		if charErr := validateJSONCharacters(data); charErr != nil {
227			return Artifact{}, nil, nil, nil, errInvalid(charErr.Error())
228		}
229		if dup := findDuplicateJSONMember(data); dup != nil {
230			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
231		}
232		strict, err := strictSubmissionJSON(data)
233		if err != nil {
234			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
235		}
236		if err := validateFormalCheckStatuses(strict); err != nil {
237			return Artifact{}, nil, nil, nil, err
238		}
239		if err := validateFormalRequiresABI(strict); err != nil {
240			return Artifact{}, nil, nil, nil, err
241		}
242		var in wireInput
243		if err := json.Unmarshal(strict, &in); err != nil {
244			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
245		}
246		invariants := make(map[string]bool, len(in.Invariants))
247		for key, raw := range in.Invariants {
248			// Only JSON true/false is a conclusion. Unmarshalling directly into a
249			// bool would turn null into the zero value false, which would falsely
250			// record a defect; require the token to be a boolean instead.
251			var token any
252			if err := json.Unmarshal(raw, &token); err != nil {
253				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
254			}
255			holds, ok := token.(bool)
256			if !ok {
257				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
258			}
259			invariants[key] = holds
260		}
261		artifact := Artifact{
262			Name:     in.Artifact.Name,
263			ABI:      in.Artifact.ABI,
264			Bytecode: in.Artifact.Bytecode,
265			Source:   in.Artifact.Source,
266		}
267		rules := make([]Rule, 0, len(in.Rules))
268		for _, wr := range in.Rules {
269			rules = append(rules, Rule{
270				ID:          wr.ID,
271				Kind:        wr.Kind,
272				Severity:    wr.Severity,
273				Invariant:   wr.Invariant,
274				RequiresABI: wr.RequiresABI,
275				Version:     wr.Version,
276			})
277		}
278		checks := make([]CheckRecord, 0, len(in.Checks))
279		for _, wc := range in.Checks {
280			checks = append(checks, CheckRecord{
281				ArtifactHash: wc.ArtifactHash,
282				RuleID:       wc.RuleID,
283				Version:      wc.Version,
284				Status:       wc.Status,
285				Note:         wc.Note,
286			})
287		}
288		return artifact, rules, invariants, checks, nil
289	}
290	
291	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
292	// bytecode and source strings contribute; field boundaries are explicit
293	// (length-prefixed) so that different splits never collide. The source is
294	// hashed as a field value, never read from disk, and the name does not
295	// participate.
296	func ArtifactHash(a Artifact) string {
297		h := sha256.New()
298		h.Write([]byte("contractsentinel-artifact-v1\n"))
299		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
300			fmt.Fprintf(h, "%d\n", len(field))
301			h.Write([]byte(field))
302		}
303		sum := h.Sum(nil)
304		return hex.EncodeToString(sum)
305	}
306	
307	// validCheckStatus reports whether status is one of the four recorded check
308	// conclusions.
309	func validCheckStatus(status string) bool {
310		switch status {
311		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
312			return true
313		}
314		return false
315	}
316	
317	// BuildReport evaluates rules against the artifact and invariant values and
318	// imported check records and produces the report to persist. Insufficient
319	// inputs (missing ABI for a rule that requires it, missing bytecode for a
320	// symbolic rule) fail the whole submission and are never recorded as defects.
321	// Imported checks are validated as a whole: unknown rules, duplicate records,
322	// unknown statuses, missing notes, hash or version mismatches, and a rule
323	// receiving both a check record and an invariant boolean all reject the
324	// submission without producing a report.
325	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
326		if artifact.Name == "" {
327			return Report{}, errInvalid("artifact name is required")
328		}
329		hash := ArtifactHash(artifact)
330		seen := make(map[string]bool, len(rules))
331		ruleByID := make(map[string]Rule, len(rules))
332		for _, rule := range rules {
333			if rule.ID == "" {
334				return Report{}, errInvalid("rule id is required")
335			}
336			if rule.Version == "" {
337				return Report{}, errInvalid("rule " + rule.ID + " version is required")
338			}
339			if seen[rule.ID] {
340				return Report{}, errInvalid("duplicate rule id " + rule.ID)
341			}
342			seen[rule.ID] = true
343			ruleByID[rule.ID] = rule
344			if rule.RequiresABI && artifact.ABI == "" {
345				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
346			}
347			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
348				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
349			}
350		}
351		checkByRule := make(map[string]CheckRecord, len(checks))
352		for _, check := range checks {
353			if check.RuleID == "" {
354				return Report{}, errInvalid("check rule id is required")
355			}
356			rule, ok := ruleByID[check.RuleID]
357			if !ok {
358				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
359			}
360			if _, dup := checkByRule[check.RuleID]; dup {
361				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
362			}
363			if check.ArtifactHash != hash {
364				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
365			}
366			if check.Version != rule.Version {
367				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
368			}
369			if !validCheckStatus(check.Status) {
370				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
371			}
372			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
373				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
374			}
375			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
376				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
377			}
378			checkByRule[check.RuleID] = check
379		}
380		report := Report{
381			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
382			Rules:    []ReportRule{},
383			Findings: []ReportFinding{},
384		}
385		for _, rule := range rules {
386			status := StatusUnchecked
387			note := ""
388			if check, ok := checkByRule[rule.ID]; ok {
389				status = check.Status
390				note = check.Note
391			} else {
392				// No imported check: the invariant booleans decide. The verdict
393				// interpretation is shared with the finding-list path in Run.
394				switch checkInvariant(rule, invariants) {
395				case invariantHolds:
396					status = StatusPass
397				case invariantViolated:
398					status = StatusDefect
399				}
400			}
401			report.Rules = append(report.Rules, ReportRule{
402				ID:          rule.ID,
403				Kind:        rule.Kind,
404				Severity:    rule.Severity,
405				Invariant:   rule.Invariant,
406				RequiresABI: rule.RequiresABI,
407				Version:     rule.Version,
408				Status:      status,
409				Note:        note,
410			})
411			if status == StatusDefect {
412				evidence := note
413				if evidence == "" {
414					evidence = invariantEvidence(rule.Invariant)
415				}
416				report.Findings = append(report.Findings, ReportFinding{
417					ArtifactHash: hash,
418					RuleID:       rule.ID,
419					Version:      rule.Version,
420					Severity:     rule.Severity,
421					Invariant:    rule.Invariant,
422					Evidence:     evidence,
423				})
424			}
425		}
426		report.ReportID = ReportID(report)
427		return report, nil
428	}
429	
430	// canonicalRule is the order-independent view of a rule used for the id. The
431	// note is omitted when empty so reports built only from invariant booleans
432	// keep their original ids.
433	type canonicalRule struct {
434		ID          string `json:"id"`
435		Kind        string `json:"kind"`
436		Severity    string `json:"severity"`
437		Invariant   string `json:"invariant"`
438		RequiresABI bool   `json:"requiresABI"`
439		Version     string `json:"version"`
440		Status      string `json:"status"`
441		Note        string `json:"note,omitempty"`
442	}
443	
444	// canonicalFinding is the order-independent view of a finding used for the id.
445	type canonicalFinding struct {
446		ArtifactHash string `json:"artifactHash"`
447		RuleID       string `json:"ruleId"`
448		Version      string `json:"version"`
449		Severity     string `json:"severity"`
450		Invariant    string `json:"invariant"`
451		Evidence     string `json:"evidence"`
452	}
453	
454	// canonicalReport is the deterministic content a report id is computed from.
455	type canonicalReport struct {
456		ArtifactHash string             `json:"artifactHash"`
457		Name         string             `json:"name"`
458		Rules        []canonicalRule    `json:"rules"`
459		Findings     []canonicalFinding `json:"findings"`
460	}
461	
462	// canonicalize renders a report into its order-independent form.
463	func canonicalize(report Report) canonicalReport {
464		cr := canonicalReport{
465			ArtifactHash: report.Artifact.Hash,
466			Name:         report.Artifact.Name,
467		}
468		for _, rule := range report.Rules {
469			cr.Rules = append(cr.Rules, canonicalRule{
470				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
471				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
472				Version: rule.Version, Status: rule.Status, Note: rule.Note,
473			})
474		}
475		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
476		for _, finding := range report.Findings {
477			cr.Findings = append(cr.Findings, canonicalFinding{
478				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
479				Version: finding.Version, Severity: finding.Severity,
480				Invariant: finding.Invariant, Evidence: finding.Evidence,
481			})
482		}
483		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
484		return cr
485	}
486	
487	// ReportID returns the content-addressed identifier of a report. The id binds
488	// the artifact hash, name, complete rule definitions, the invariant value
489	// used by each rule (unchecked and explicit pass are distinct), and the
490	// findings. Rule order, invariant key order and unrelated invariant keys do
491	// not influence it.
492	func ReportID(r Report) string {
493		data, err := json.Marshal(canonicalize(r))
494		if err != nil {
495			panic(err) // canonical values are all strings and bools
496		}
497		sum := sha256.Sum256(data)
498		return hex.EncodeToString(sum[:])
499	}
500	
501	// validateReport checks every archive legality condition against r. It is the
502	// single definition of a legal report: the id and artifact hash are 64
503	// lowercase hex characters, the id matches the content, the artifact name is
504	// present, rule ids are present and unique with non-empty versions, statuses
505	// use the five recorded values, tool-missing and timeout notes are
506	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
507	// artifact hash, version, severity, invariant and evidence match the rule.
508	// The same conditions apply to submissions and to stored archives: a
509	// recomputed id never makes an invalid report legal. fail is errInvalid for
510	// submissions and errCorrupt for stored archives.
511	func validateReport(r Report, fail func(string) error) error {
512		if !validReportID(r.ReportID) {
513			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
514		}
515		if r.Artifact.Name == "" {
516			return fail("report " + r.ReportID + " artifact name is required")
517		}
518		if !validReportID(r.Artifact.Hash) {
519			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
520		}
521		if ReportID(r) != r.ReportID {
522			return fail("report content does not match id " + r.ReportID)
523		}
524		seenRule := make(map[string]bool, len(r.Rules))
525		defectByID := make(map[string]ReportRule)
526		for _, rule := range r.Rules {
527			if rule.ID == "" {
528				return fail("report " + r.ReportID + " has a rule with an empty id")
529			}
530			if seenRule[rule.ID] {
531				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
532			}
533			seenRule[rule.ID] = true
534			if rule.Version == "" {
535				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
536			}
537			switch rule.Status {
538			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
539			default:
540				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
541			}
542			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
543				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
544			}
545			if rule.Status == StatusDefect {
546				defectByID[rule.ID] = rule
547			}
548		}
549		seenFinding := make(map[string]bool, len(r.Findings))
550		for _, f := range r.Findings {
551			if f.RuleID == "" {
552				return fail("report " + r.ReportID + " has a finding with an empty rule id")
553			}
554			rule, ok := defectByID[f.RuleID]
555			if !ok {
556				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
557			}
558			if seenFinding[f.RuleID] {
559				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
560			}
561			seenFinding[f.RuleID] = true
562			if f.ArtifactHash != r.Artifact.Hash {
563				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
564			}
565			if f.Version != rule.Version {
566				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
567			}
568			if f.Severity != rule.Severity {
569				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
570			}
571			if f.Invariant != rule.Invariant {
572				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
573			}
574			wantEvidence := rule.Note
575			if wantEvidence == "" {
576				wantEvidence = invariantEvidence(rule.Invariant)
577			}
578			if f.Evidence != wantEvidence {
579				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
580			}
581		}
582		for id := range defectByID {
583			if !seenFinding[id] {
584				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
585			}
586		}
587		return nil
588	}
589	
590	// validStoredReport validates archive contents.
591	func validStoredReport(r Report) error {
592		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
593	}
594	
595	// validSubmittedReport validates a submission before any store operation.
596	func validSubmittedReport(r Report) error {
597		return validateReport(r, func(msg string) error { return errInvalid(msg) })
598	}
599	
600	// firstInvalidUTF8ByteInString returns the first byte that is not valid UTF-8
601	// inside s. A Go string can carry any bytes, including bytes no JSON text may
602	// contain: json.Marshal (and therefore the canonical marshalling inside
603	// ReportID) silently replaces such a byte with U+FFFD instead of failing, so
604	// neither the id/content check nor the archive round trip can see it.
605	func firstInvalidUTF8ByteInString(s string) (byte, bool) {
606		for i := 0; i < len(s); {
607			r, size := utf8.DecodeRuneInString(s[i:])
608			if r == utf8.RuneError && size == 1 {
609				return s[i], true
610			}
611			i += size
612		}
613		return 0, false
614	}
615	
616	// validateSubmittedText is the in-memory counterpart of the JSON character
617	// gates in ParseAuditInput and loadStoredReport. SaveReport accepts a Report
618	// built directly by a Go caller, whose strings never passed through JSON
619	// decoding; encoding/json marshals such a value without an error while
620	// replacing every invalid UTF-8 byte with U+FFFD, and ReportID computes from
621	// the same rewritten canonical form, so the recomputed id and the
622	// rule/finding correspondence would all match an archive whose text no
623	// longer equals what the caller handed over. Every caller-supplied string is
624	// therefore checked on the raw object — reportId, artifact name and hash,
625	// each rule definition field and status note, and each finding binding field
626	// and evidence — independently of which rules produced defects and of
627	// whether the report carries any finding at all. The rejection is an input
628	// error naming the exact field, with the array position of rules and
629	// findings, and it runs before any filesystem operation.
630	func validateSubmittedText(r Report) error {
631		check := func(field, value string) error {
632			if b, bad := firstInvalidUTF8ByteInString(value); bad {
633				return errInvalid(fmt.Sprintf("invalid UTF-8 byte 0x%02x in report field %s", b, field))
634			}
635			return nil
636		}
637		if err := check("reportId", r.ReportID); err != nil {
638			return err
639		}
640		if err := check("artifact.name", r.Artifact.Name); err != nil {
641			return err
642		}
643		if err := check("artifact.hash", r.Artifact.Hash); err != nil {
644			return err
645		}
646		ruleFields := []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
647		for i, rule := range r.Rules {
648			values := []string{rule.ID, rule.Kind, rule.Severity, rule.Invariant, rule.Version, rule.Status, rule.Note}
649			for j, value := range values {
650				if err := check(fmt.Sprintf("rules[%d].%s", i, ruleFields[j]), value); err != nil {
651					return err
652				}
653			}
654		}
655		findingFields := []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}
656		for i, finding := range r.Findings {
657			values := []string{finding.ArtifactHash, finding.RuleID, finding.Version, finding.Severity, finding.Invariant, finding.Evidence}
658			for j, value := range values {
659				if err := check(fmt.Sprintf("findings[%d].%s", i, findingFields[j]), value); err != nil {
660					return err
661				}
662			}
663		}
664		return nil
665	}
666	
667	// duplicateArchiveError classifies an archive that repeats a JSON member as
668	// corrupt and names the requested report id, the decoded member name and the
669	// object carrying it (with array position and rule id when applicable).
670	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
671		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
672	}
673	
674	// characterArchiveError classifies an archive whose bytes are not legal JSON
675	// text — an invalid UTF-8 byte anywhere, or an unpaired / wrongly ordered
676	// surrogate escape inside any member name or string value, including unknown
677	// extension members — as corrupt and names the requested report id together
678	// with the precise byte offset, line/column and JSON path. It is the
679	// read-side counterpart of the submission gate in ParseAuditInput: the decode
680	// below would otherwise replace both problems with U+FFFD and could accept a
681	// rewritten archive whose id and rule/finding evidence happened to match.
682	func characterArchiveError(id string, charErr *charEncodingError) error {
683		return errCorrupt("report " + id + " archive is corrupt: " + charErr.Error())
684	}
685	
686	// reportShape is the fixed-field shape of a stored report archive: the agreed
687	// spellings at the top level and inside the artifact, every rule and every
688	// finding. The trusted content of a report is carried by these fixed fields
689	// alone; case variants, whitespace-padded names and unknown members are
690	// extension data and never reach the decoder.
691	var reportShape = fixedShape{
692		keys: []string{"reportId", "artifact", "rules", "findings"},
693		objects: map[string]fixedShape{
694			"artifact": {keys: []string{"name", "hash"}},
695		},
696		arrays: map[string]fixedShape{
697			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
698			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
699		},
700	}
701	
702	// strictReportJSON rewrites archive bytes to the fixed report fields under
703	// their original spelling; see fixedShape for the recognition convention
704	// shared with the submission side.
705	func strictReportJSON(data []byte) ([]byte, error) {
706		return strictFixedJSON(data, reportShape)
707	}
708	
709	// validateArchiveRuleFields is the read-side counterpart of the submission
710	// gate in validateFormalRequiresABI. A ReportRule's typed members are Go
711	// bool/string fields, so decoding the strict archive straight into Report
712	// turns a formal null member into the zero value false or "": an archive that
713	// wrote "requiresABI":null, or "note":null on a passing rule without a note,
714	// would read byte-for-byte like one that omitted the member, the recomputed
715	// id and the rule/finding correspondence would all pass on that laundered
716	// value, and a diff could even compare the rule as unchanged. The shared
717	// checkRuleFieldTypes gate therefore inspects each written formal member's
718	// raw JSON token before that decoding happens. null or any other
719	// non-required type makes the whole archive corrupt, independently of the
720	// rule's check status and of whether it has a finding — the offending rule is
721	// never skipped and no partial report is returned. An omitted member still
722	// decodes to the zero value and an explicit empty string is still judged by
723	// the ordinary business rules: the string gate is about the JSON type alone,
724	// not about requiring text to be non-empty. The strict rewrite dropped
725	// extension members, so a case-variant or whitespace-padded name is invisible
726	// here: a correctly typed value it carries neither supplies nor rescues the
727	// formal value, and a null it carries never reaches this gate. locate renders
728	// the rule locator in the wording each gate historically used, and every
729	// error names the requested report id and is classified as archive
730	// corruption.
731	func validateArchiveRuleFields(strict []byte, id string, checks []ruleFieldTypeCheck,
732		locate func(int, map[string]json.RawMessage) string) error {
733		return checkRuleFieldTypes(strict, checks, ruleFieldTypeHooks{
734			locate: locate,
735			invalidJSON: func(err error) error {
736				return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
737			},
738			reject: func(where, field string, typ ruleFieldType) error {
739				return errCorrupt("report " + id + " archive is corrupt: " + where + ": " + field + " " + typ.requirement())
740			},
741		})
742	}
743	
744	// archiveRuleLocator names a rule in an archive error by its formal id
745	// ("rule r-bad"), falling back to "rule" when the id is missing, empty or not
746	// itself a legal string. It deliberately carries no rules-array position.
747	func archiveRuleLocator(_ int, rule map[string]json.RawMessage) string {
748		if ruleID := formalRuleID(rule); ruleID != "" {
749			return "rule " + ruleID
750		}
751		return "rule"
752	}
753	
754	// archiveRulePositionLocator names a rule's position in the rules array
755	// ("rules[1]") and, when the rule carries a legal non-empty id, also names it
756	// ("rules[1] (rule r-bad)").
757	func archiveRulePositionLocator(i int, rule map[string]json.RawMessage) string {
758		where := fmt.Sprintf("rules[%d]", i)
759		if ruleID := formalRuleID(rule); ruleID != "" {
760			where += " (rule " + ruleID + ")"
761		}
762		return where
763	}
764	
765	// validateArchiveRequiresABI runs the read-side boolean gate for the formal
766	// requiresABI member.
767	func validateArchiveRequiresABI(strict []byte, id string) error {
768		return validateArchiveRuleFields(strict, id,
769			[]ruleFieldTypeCheck{{field: "requiresABI", typ: ruleFieldBoolean}},
770			archiveRuleLocator)
771	}
772	
773	// archiveRuleTextFields lists the formal rule members whose value, once the
774	// member is written out, must be a JSON string.
775	var archiveRuleTextFields = []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
776	
777	// validateArchiveRuleText runs the read-side string gate for the text fields
778	// of every stored rule; see validateArchiveRuleFields for why the raw token is
779	// checked before decoding.
780	func validateArchiveRuleText(strict []byte, id string) error {
781		checks := make([]ruleFieldTypeCheck, len(archiveRuleTextFields))
782		for i, field := range archiveRuleTextFields {
783			checks[i] = ruleFieldTypeCheck{field: field, typ: ruleFieldString}
784		}
785		return validateArchiveRuleFields(strict, id, checks, archiveRulePositionLocator)
786	}
787	
788	// loadStoredReport parses archive bytes for id and fully validates them.
789	func loadStoredReport(data []byte, id string) (Report, error) {
790		// Read-side counterpart of the submission character gate in
791		// ParseAuditInput. As with a repeated member, json.Unmarshal silently
792		// rewrites an invalid UTF-8 byte and an unpaired or wrongly ordered
793		// surrogate escape into U+FFFD, so an archive whose note and evidence both
794		// carried the substitution character could have those two spots changed to
795		// lone surrogate escapes and still decode to byte-identical content: the
796		// recomputed id and the rule/finding evidence comparison would then pass on
797		// the rewritten copy. Every raw string literal is checked first — member
798		// names and values, at every depth, inside unknown extension members too —
799		// and the whole archive is corrupt when any character is illegal, whatever
800		// id the rewritten content would compute.
801		if charErr := validateJSONCharacters(data); charErr != nil {
802			return Report{}, characterArchiveError(id, charErr)
803		}
804		// Read-side counterpart of the submission check: json.Unmarshal silently
805		// keeps the last value for a repeated member, so an archive that writes a
806		// rule status as 发现缺陷 and then 通过 would decode to whichever came
807		// last. The recomputed id and the rule/finding correspondence all operate
808		// on that last-wins value and could therefore pass, accepting an archive
809		// with two conflicting conclusions. Any repeated member in any object
810		// makes the archive corrupt, regardless of the last value.
811		if dup := findDuplicateJSONMember(data); dup != nil {
812			return Report{}, duplicateArchiveError(id, data, dup)
813		}
814		strict, err := strictReportJSON(data)
815		if err != nil {
816			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
817		}
818		// Check the formal requiresABI member against its raw JSON token before
819		// decoding into the Go bool below; otherwise a null value would silently
820		// become the zero value false and could pass every later check, including
821		// the content id, as if the archive had explicitly said false.
822		if err := validateArchiveRequiresABI(strict, id); err != nil {
823			return Report{}, err
824		}
825		// Same laundering hazard for the rule text fields: decoding into a Go
826		// string turns a formal null member into "", so an archive that wrote
827		// "note":null on a note-less passing rule would pass every later check,
828		// including the content id, as if the member had been omitted. Check the
829		// raw JSON token of every written formal text member before decoding.
830		if err := validateArchiveRuleText(strict, id); err != nil {
831			return Report{}, err
832		}
833		var r Report
834		if err := json.Unmarshal(strict, &r); err != nil {
835			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
836		}
837		if r.ReportID != id {
838			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
839		}
840		if err := validStoredReport(r); err != nil {
841			return Report{}, err
842		}
843		return r, nil
844	}
845	
846	// saveReportHook, when set, is invoked after the archive existence check and
847	// before the atomic publish. It lets tests simulate another process racing to
848	// claim the same report id.
849	var saveReportHook func(finalPath string)
850	
851	// SaveReport persists a report under the store directory. The store is safe
852	// for concurrent writers: identical reports share one file and all
853	// submissions succeed, different reports never overwrite each other, and
854	// readers only ever observe complete files. A submission is fully validated
855	// before any store operation, so an invalid report creates no store and no
856	// files. Every string in a directly constructed report must be valid UTF-8:
857	// json.Marshal would otherwise rewrite an invalid byte to U+FFFD while the
858	// content-addressed id matched the rewritten copy, reporting success for an
859	// archive whose text differs from the caller's; such a report is rejected as
860	// an input error before the store directory is touched. A pre-existing file
861	// with the same id must be a valid archive of the same report; a corrupted
862	// archive makes the submission fail while keeping the original file, even
863	// when the corruption appears only during the save. The first successfully
864	// archived bytes are never replaced by later submissions.
865	func SaveReport(dir string, r Report) error {
866		if err := validateSubmittedText(r); err != nil {
867			return err
868		}
869		if err := validSubmittedReport(r); err != nil {
870			return err
871		}
872		if err := os.MkdirAll(dir, 0o755); err != nil {
873			return err
874		}
875		finalPath := filepath.Join(dir, r.ReportID+".json")
876		if existing, err := os.ReadFile(finalPath); err == nil {
877			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
878				return err
879			}
880			return nil
881		} else if !os.IsNotExist(err) {
882			return err
883		}
884		data, err := json.Marshal(r)
885		if err != nil {
886			return err
887		}
888		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
889		if err != nil {
890			return err
891		}
892		tmpPath := tmp.Name()
893		cleanup := func() { os.Remove(tmpPath) }
894		if _, err := tmp.Write(data); err != nil {
895			tmp.Close()
896			cleanup()
897			return err
898		}
899		if err := tmp.Sync(); err != nil {
900			tmp.Close()
901			cleanup()
902			return err
903		}
904		if err := tmp.Close(); err != nil {
905			cleanup()
906			return err
907		}
908		if saveReportHook != nil {
909			saveReportHook(finalPath)
910		}
911		if err := os.Link(tmpPath, finalPath); err != nil {
912			cleanup()
913			if os.IsExist(err) {
914				existing, readErr := os.ReadFile(finalPath)
915				if readErr != nil {
916					return readErr
917				}
918				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
919					return err
920				}
921				return nil
922			}
923			return err
924		}
925		cleanup()
926		return nil
927	}
928	
929	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
930	// hex characters; missing, corrupted or tampered archives produce a clear
931	// error. The store is only read, never created or modified.
932	func LoadReport(dir, id string) (Report, error) {
933		if !validReportID(id) {
934			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
935		}
936		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
937		if err != nil {
938			if os.IsNotExist(err) {
939				return Report{}, errNotFound("report " + id + " not found")
940			}
941			return Report{}, err
942		}
943		return loadStoredReport(data, id)
944	}
945	
946	type errNotFound string
947	
948	func (e errNotFound) Error() string { return string(e) }
949	
950	type errCorrupt string
951	
952	func (e errCorrupt) Error() string { return string(e) }
953

